from flask import Blueprint, render_template, jsonify
from flask_login import login_required, current_user
from .services import get_default_camps, get_personalized_camps
from . import recommend_bp


@recommend_bp.route("/")
def index():
    # 页面初始先给默认推荐，前端加载后再请求个性化接口覆盖
    results = get_default_camps(limit=6)
    return render_template("recommend/index.html", results=results)


@recommend_bp.route("/api/personalized")
@login_required
def api_personalized():
    print("=== HIT /recommend/api/personalized ===")
    print("=== current_user.id ===", current_user.id)

    results = get_personalized_camps([], limit=6)

    safe_results = []
    for item in results:
        camp = item["camp"]

        safe_results.append({
            "score": round(float(item.get("score", 0)), 4),
            "camp": {
                "id": camp.id,
                "name": camp.name,
                "city": camp.city,
                "district": camp.district,
                "address": camp.address,
                "price_text": camp.price_text,
                "price_min": camp.price_min,
                "rating": camp.rating,
                "facilities": camp.facilities,
                "crowd_tags": camp.crowd_tags,
                "cover_image": camp.cover_image,
                "detail_url": camp.detail_url,
                "latitude": camp.latitude,
                "longitude": camp.longitude,
            }
        })

    return jsonify(safe_results)

from flask import Blueprint, render_template, jsonify
from flask_login import login_required, current_user
from .services import get_default_camps, get_personalized_camps
from . import recommend_bp


@recommend_bp.route("/")
def index():
    # 页面初始先给默认推荐，前端加载后再请求个性化接口覆盖
    camps = get_default_camps(limit=6)
    results = [{"camp": camp, "score": None} for camp in camps]
    return render_template("recommend/index.html", results=results)


@recommend_bp.route("/api/personalized")
@login_required
def api_personalized():
    print("=== HIT /recommend/api/personalized ===")
    print("=== current_user.id ===", current_user.id)

    results = get_personalized_camps([], limit=6)

    safe_results = []
    for item in results:
        camp = item["camp"]

        safe_results.append({
            "score": round(float(item.get("score", 0)), 4),
            "camp": {
                "id": camp.id,
                "name": camp.name,
                "city": camp.city,
                "district": camp.district,
                "address": camp.address,
                "price_text": camp.price_text,
                "price_min": camp.price_min,
                "rating": camp.rating,
                "facilities": camp.facilities,
                "crowd_tags": camp.crowd_tags,
                "cover_image": camp.cover_image,
                "detail_url": camp.detail_url,
                "latitude": camp.latitude,
                "longitude": camp.longitude,
            }
        })

    return jsonify(safe_results)
